__NUXT_JSONP__("/fr/stay", (function(a,b,c,d,e,f,g,h,i){return {data:[{details:{slug:"fr",pageTitle:"Accommodations | Mentor Language Institute",pageDescription:"MLI works with U.S. Support Services Inc. to provide housing for MLI students. ",title:"Accommodations",subtitle:["MLI works with U.S. Support Services Inc. to provide housing for MLI students. \u003Cbr \u002F\u003EFor more details, please visit \u003Ca href=\"www.usssinc.net\u002Ffr\" target=\"_blank\"\u003Ewww.usssinc.net\u002Ffr\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Les étudiants peuvent choisir soit le séjour en famille d'acceuil, soit en dortoir.",types:[{title:"Dortoir",description:["Il y a 40 chambres dans les dortoirs et beaucoup d'occasions de communiquer avec d'autres étudiants internationaux. Nous vous conseillons le dortoir si vous avez un budget limité."],lists:["Chambres : Privée, Shared (2 personnes) ou Quad (4 personnes)","Repas: repas non fourni [une cuisine entièrement équipée est disponible]","Intimité: Les dortoirs sont plus intimes que les séjours en famille d'accueil. Cependant, il existe des règles spécifiques pour les dortoirs.","Trajet: environ 20 minutes à pied ou en bus."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Prix des dortoirs",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E Si vous avez moins de 18 ans, le loyer sera environ 10% plus élevé que le prix pour une personne de plus de 18 ans.",thead:[b,"Privée","Partagée (2 personnes)","Quad (4 personnes)"],tbody:[[c,a,a,a],[d,"$550","$410",a],[e,"$1,100","$820","$600"],[f,"$1,650","$1,230","$900"],[g,"$2,200","$1,640","$1,200"],[h,"$4,160","$2,960","$2,160"],[i,"$6,240","$4,440","$3,240"]]},notes:["*Les frais de placement sont un paiement unique. Ce n'est pas remboursable.\u003Cbr \u002F\u003E**La caution sera remboursée après le départ des étudiants."]}]},{title:"Famille d'acceuil",description:["Les étudiants qui choisissent de vivre dans une famille d'accueil recherchent un endroit sûr, accueillant, et une atmosphère confortable dans laquelle ils peuvent pratiquer leurs compétences en anglais. C'est aussi l'occasion de découvrir les coutumes, les traditions et les valeurs familiales américaines."],lists:["Chambre: Privée","Repas: 2 repas par jour (petit déjeuner et dîner)","Intimité: les règles dépendent de la famille d'accueil.","Trajet: 30-45 minutes en moyenne par bus"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Prix de séjour en famille d'acceuil",table:{tableMaxCol:3,title:"Frais de placement* : 300$\u003Cbr \u002F\u003E Si vous avez moins de 18 ans, le loyer sera environ 10% plus élevé que le prix pour une personne de plus de 18 ans.",thead:[b,"Chambre privée","Partagée***"],tbody:[[c,a,a],[d,"436$","384$"],[e,"872$","768$"],[f,"1,308$","1,152$"],[g,"$1,744","$1,536"],[h,"$3,160","$2,904"],[i,"$4,740","$4,356"]]},notes:["*Les frais de placement sont un paiement unique. Ce n'est pas remboursable.\u003Cbr \u002F\u003E**La caution sera remboursée après le départ des étudiants.\u003Cbr \u002F\u003E***Si vous demandez une chambre partagée chez la famille d'acceuil,  \u003Cspan class=\"rmarker\"\u003Evous devez faire la demande avec l'autre personne\u003C\u002Fspan\u003E"]}]}],comments:{title:"Commentaires de notre personnel",description:["Il n'est pas facile de trouver un lieu de séjour lors de votre arrivée aux États-Unis, en particulier pour les étudiants internationaux qui n'ont pas de numéro de sécurité sociale (SSN) et de crédit. La plupart des endroits exigent à la fois un SSN et un historique de crédit pour louer une place. Par conséquent, nous vous recommandons de rester dans nos logements pour au moins les deux premiers mois.","※ Votre hébergement sera assuré par U.S. Support Service Inc. ou d'autres agents."]},dir:"\u002Fstay",path:"\u002Fstay\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:31.098Z",updatedAt:"2025-05-26T12:06:27.919Z"}}],fetch:{},mutations:void 0}}("$300","","\u003Cb\u003ECaution**\u003C\u002Fb\u003E","1 semaine","2 semaines","3 semaines","4 semaines","8 semaines","12 semaines")));